"""Little mouse-drawn scenery props. Standard-library SVG sources; no packages."""
from pathlib import Path
OUT=Path(__file__).resolve().parents[1]/'public'/'sprites'
OUT.mkdir(exist_ok=True)

def draw(name,w,h,body):
    (OUT/f'scene-{name}.svg').write_text(f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><defs><filter id="mouse" x="-5%" y="-5%" width="110%" height="110%"><feTurbulence baseFrequency=".07" numOctaves="2" seed="13" result="noise"/><feDisplacementMap in="SourceGraphic" in2="noise" scale=".8"/></filter></defs><g fill="none" stroke="#544b50" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" filter="url(#mouse)">{body}</g></svg>''')

draw('mountains',640,240,'''<path d="M0 151 45 133l49 17 58-69 51 57 54-25 54 26 87-90 56 51 44-14 67 50 75-35v139H0Z" fill="#32303d" stroke="#484151"/><path d="m126 111 26-30 24 28-17-7-8 11-7-8Zm245-33 27-29 30 28-18-7-11 11-10-9Z" fill="#5b5261" stroke="#5b5261"/><path d="m49 161 26-8 13 4m121-7 28-11 16 7m204-37 20-4 21 10" stroke="#514553"/><path d="m341 154 50-63 21 37m-282 50 26-33 15 19" stroke="#282a35" stroke-width="3"/>''')
