draw('cloud',160,80,'''<path d="M14 57C1 35 23 20 43 31c-3-30 51-30 56-6 31-15 56 7 48 27 20 15-6 26-24 22l-97 1C8 75 1 62 14 57Z" fill="#dedec5" stroke="#9ca99b"/><path d="M24 39q6-9 18-5m18-15q13-7 23 0m25 18 12-1" stroke="#f2edd3" stroke-width="3"/><path d="m26 63 40 1m30-4 28 1" stroke="#c6ceb5"/>''')
